import React, { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { fetchJobs } from "../Features/JobSlice"; // Function from Redux to get all jobs from MongoDB
import "../Styles/FindJob.css";

const FindJob = () => {
  const dispatch = useDispatch(); // Used to trigger Redux actions
  const { jobs, isLoading } = useSelector((state) => state.jobs); // Access job data and loading state from Redux store

  const [searchTerm, setSearchTerm] = useState(""); // Local state for search input

  // When the page loads → fetch all jobs from MongoDB
  useEffect(() => {
    dispatch(fetchJobs()); // Call the Redux function to load all jobs
  }, [dispatch]);

  // Filter the jobs based on what user types in the search bar
  const filteredJobs = jobs.filter(
    (job) =>
      job.jobTitle.toLowerCase().includes(searchTerm.toLowerCase()) ||
      job.organization.toLowerCase().includes(searchTerm.toLowerCase()) ||
      job.skills.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // When user clicks “Apply” → store job info in localStorage (temporary)
  const handleApply = (job) => {
    const existingApplications =
      JSON.parse(localStorage.getItem("applications")) || [];

    // Prevent applying for the same job twice
    const alreadyApplied = existingApplications.some(
      (appliedJob) => appliedJob.jobTitle === job.jobTitle
    );

    if (alreadyApplied) {
      alert("You have already applied for this job.");
      return;
    }

    // Add the new application and save it locally
    const updatedApplications = [...existingApplications, job];
    localStorage.setItem("applications", JSON.stringify(updatedApplications));
    alert("Job applied successfully!");
  };

  // Show a loading message while fetching jobs from server
  if (isLoading) return <p>Loading jobs...</p>;

  return (
    <div className="findjob-page">
      <h1 className="findjob-title">
        Find <span className="accent">Job</span>
      </h1>

      {/* Search bar section */}
      <div className="search-container">
        <div className="search-wrapper">
          <input
            type="text"
            placeholder="Search skills, companies"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)} // Update search term
            className="search-box"
          />
        </div>
        <button className="search-btn">Search</button>
      </div>

      {/* Display job cards */}
      <div className="job-list">
        {filteredJobs.length === 0 ? (
          <p className="no-jobs">No jobs found.</p>
        ) : (
          filteredJobs.map((job, index) => (
            <div key={index} className="job-card">
              <div className="job-header">
                <h3>{job.jobTitle}</h3>
                <span className="rate">
                  {job.rate} OMR · {job.rateType}
                </span>
              </div>

              <p className="org-name">{job.organization}</p>

              {/* Tags to show category, sector, and payout */}
              <div className="tags">
                <span className="tag">{job.sector}</span>
                <span className="tag">{job.category}</span>
                {job.payout && <span className="tag">{job.payout}</span>}
              </div>

              {/* Description and required skills */}
              <p className="desc">{job.description}</p>
              <p className="skills">Skills: {job.skills}</p>

              {/* Button to apply for job */}
              <div className="job-actions">
                <button className="btn-apply" onClick={() => handleApply(job)}>
                  Apply ➜
                </button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default FindJob;
